def move(name, entry_name, config=None):
    """
    Move an entry to the sshconfig.
    """
    if config is None:
        config = Config()

    entry = config.get_entry(entry_name)
    if entry is None:
        raise ValueError("Entry not found: %s" % entry_name)

    if name in config.entries:
        raise ValueError("Entry already exists: %s" % name)

    config.entries[name] = entry
    config.save()

